def comps_of(g,bg):
    Hh,Ww=len(g),len(g[0]); seen=[[False]*Ww for _ in range(Hh)]; out=[]
    for i in range(Hh):
        for j in range(Ww):
            if g[i][j]!=bg and not seen[i][j]:
                st=[(i,j)]; comp=[]; c=g[i][j]
                while st:
                    y,x=st.pop()
                    if seen[y][x] or g[y][x]!=c: continue
                    seen[y][x]=True; comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
